import { 
  MeshBasicNodeMaterial, 
  MeshStandardNodeMaterial, 
  MeshPhysicalNodeMaterial 
} from 'three/webgpu';
import { 
  attribute, 
  uniform, 
  color, 
  mix 
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, IcosahedronGeometry, InstancedMesh, Matrix4, Vector3, Color, PointLight, PlaneGeometry } = ctx.THREE;
  const group = new Group();
  const timelines = [];

  // --- STAGE BACKDROP ---
  // Large background plane at z=-5.0 (behind the particle shell)
  const bgGeo = new PlaneGeometry(18, 14);
  const bgMat = new MeshBasicNodeMaterial();
  const vUv = attribute('uv');
  bgMat.colorNode = mix(color('#0b0b10'), color('#16161d'), vUv.y);
  bgMat.depthWrite = false;
  const bgMesh = new Mesh(bgGeo, bgMat);
  bgMesh.position.set(0, 0, -5.0);
  group.add(bgMesh);

  // --- LOCAL ACCENT LIGHTING ---
  const rawAccentColor = new Color('#ff2a38');
  const accentLight = new PointLight(rawAccentColor, 1.4, 8);
  accentLight.position.set(2, -1, 1);
  group.add(accentLight);

  // --- PARTICLES GENERATION ---
  const fieldCount = 1200;
  const coreCount = 90;

  const baseGeom = new IcosahedronGeometry(0.012, 1);

  // 1. Field Particles material and InstancedMesh
  const fieldMat = new MeshStandardNodeMaterial({
    color: '#e8ecf2',
    roughness: 1.0,
    metalness: 0.0
  });
  fieldMat.emissiveNode = color('#e8ecf2').mul(0.9);

  const fieldInst = new InstancedMesh(baseGeom, fieldMat, fieldCount);
  group.add(fieldInst);

  // 2. Core Particles material and InstancedMesh
  const coreMat = new MeshPhysicalNodeMaterial({
    color: '#ff2a38',
    transparent: true,
    blending: ctx.THREE.AdditiveBlending,
    depthWrite: false
  });
  const coreEmissiveIntensity = uniform(1.5);
  coreMat.emissiveNode = color('#ff2a38').mul(coreEmissiveIntensity);

  const coreInst = new InstancedMesh(baseGeom, coreMat, coreCount);
  group.add(coreInst);

  // Generate distributions and populate positions
  const dummy = new Matrix4();
  const pos = new Vector3();

  // Field: Ellipsoidal shell 6 x 4 x 5 centered at [0,0,-1.5]
  const fieldData = [];
  const fieldCenter = new Vector3(0, 0, -1.5);
  for (let i = 0; i < fieldCount; i++) {
    const theta = Math.acos(2 * Math.random() - 1);
    const phi = Math.random() * Math.PI * 2;
    const r = 0.35 + Math.random() * 0.65;

    const rx = (6 / 2) * r;
    const ry = (4 / 2) * r;
    const rz = (5 / 2) * r;

    pos.x = rx * Math.sin(theta) * Math.cos(phi) + fieldCenter.x;
    pos.y = ry * Math.sin(theta) * Math.sin(phi) + fieldCenter.y;
    pos.z = rz * Math.cos(theta) + fieldCenter.z;

    fieldData.push({
      anchor: pos.clone(),
      phaseX: Math.random() * Math.PI * 2,
      phaseY: Math.random() * Math.PI * 2,
      phaseZ: Math.random() * Math.PI * 2,
      scale: 0
    });

    dummy.setPosition(pos);
    fieldInst.setMatrixAt(i, dummy);
  }

  // Core: 90 instances within a 0.5 sphere at origin
  const coreData = [];
  for (let i = 0; i < coreCount; i++) {
    const theta = Math.acos(2 * Math.random() - 1);
    const phi = Math.random() * Math.PI * 2;
    const r = Math.random() * 0.5;

    pos.x = r * Math.sin(theta) * Math.cos(phi);
    pos.y = r * Math.sin(theta) * Math.sin(phi);
    pos.z = r * Math.cos(theta);

    coreData.push({
      anchor: pos.clone(),
      phaseX: Math.random() * Math.PI * 2,
      phaseY: Math.random() * Math.PI * 2,
      phaseZ: Math.random() * Math.PI * 2,
      scale: 0
    });

    dummy.setPosition(pos);
    coreInst.setMatrixAt(i, dummy);
  }

  fieldInst.instanceMatrix.needsUpdate = true;
  coreInst.instanceMatrix.needsUpdate = true;

  // --- TYPOGRAPHY PLANE AT Z=0.5 ---
  const textGroup = new Group();
  textGroup.position.z = 0.5;
  group.add(textGroup);

  // Hero Text
  const hHero = ctx.fontAtlas.createText('NOVA ATELIER', {
    fontSize: 0.62,
    color: '#e8ecf2',
    align: 'center'
  });
  hHero.position.y = 1.0;
  textGroup.add(hHero);

  // Subhead Text
  const hSub = ctx.fontAtlas.createText('Precision instruments for the dark hours.', {
    fontSize: 0.2,
    color: '#e8ecf2',
    align: 'center'
  });
  hSub.position.y = 0.25;
  textGroup.add(hSub);

  // Caption Text
  const hCap = ctx.fontAtlas.createText('EST. 2019 / GENEVA AND KYOTO', {
    fontSize: 0.09,
    color: '#ff2a38',
    align: 'center',
    letterSpacingPx: 8
  });
  hCap.position.y = -2.25;
  textGroup.add(hCap);

  // --- ANIMATIONS & CORE DRIFT UPDATE ---
  // Core Pulsing
  const pulseTl = gsap.timeline({ repeat: -1 });
  pulseTl.to(coreEmissiveIntensity, {
    value: 1.8,
    duration: 5,
    ease: 'sine.inOut'
  }).to(coreEmissiveIntensity, {
    value: 1.5,
    duration: 5,
    ease: 'sine.inOut'
  });
  timelines.push(pulseTl);

  // Emerge entrance logic via GSAP custom scale/pos driver
  const animProxy = { progress: 0 };
  const emergeTl = gsap.to(animProxy, {
    progress: 1,
    duration: 1.4,
    ease: 'power3.out',
    onUpdate: () => {
      const p = animProxy.progress;
      for (let i = 0; i < fieldCount; i++) {
        const item = fieldData[i];
        const dist = item.anchor.length();
        const startThreshold = dist * 0.15;
        const localProgress = Math.max(0, Math.min(1, (p - startThreshold) / (1 - startThreshold)));
        item.scale = localProgress;
      }
      for (let i = 0; i < coreCount; i++) {
        const item = coreData[i];
        const dist = item.anchor.length();
        const startThreshold = dist * 0.1;
        const localProgress = Math.max(0, Math.min(1, (p - startThreshold) / (1 - startThreshold)));
        item.scale = localProgress;
      }
    }
  });
  timelines.push(emergeTl);

  // Animation frame updater for slow orbit drift & matrix applying
  let frameId;
  const currentPos = new Vector3();
  const scaleVector = new Vector3();

  const update = () => {
    frameId = requestAnimationFrame(update);
    const timeSecs = performance.now() * 0.001;
    const driftFreq = 0.05 * Math.PI * 2;

    // Update field
    for (let i = 0; i < fieldCount; i++) {
      const data = fieldData[i];
      const ox = Math.sin(timeSecs * driftFreq + data.phaseX) * 0.04;
      const oy = Math.sin(timeSecs * driftFreq + data.phaseY) * 0.04;
      const oz = Math.sin(timeSecs * driftFreq + data.phaseZ) * 0.04;

      currentPos.set(data.anchor.x + ox, data.anchor.y + oy, data.anchor.z + oz);
      dummy.setPosition(currentPos);

      scaleVector.setScalar(data.scale);
      dummy.scale(scaleVector);

      fieldInst.setMatrixAt(i, dummy);
    }
    fieldInst.instanceMatrix.needsUpdate = true;

    // Update core
    for (let i = 0; i < coreCount; i++) {
      const data = coreData[i];
      const ox = Math.sin(timeSecs * driftFreq + data.phaseX) * 0.04;
      const oy = Math.sin(timeSecs * driftFreq + data.phaseY) * 0.04;
      const oz = Math.sin(timeSecs * driftFreq + data.phaseZ) * 0.04;

      currentPos.set(data.anchor.x + ox, data.anchor.y + oy, data.anchor.z + oz);
      dummy.setPosition(currentPos);

      scaleVector.setScalar(data.scale);
      dummy.scale(scaleVector);

      coreInst.setMatrixAt(i, dummy);
    }
    coreInst.instanceMatrix.needsUpdate = true;
  };
  update();

  // Apply Cinematic Primitives
  const configuredPrimitives = config.cinematicPrimitives ?? [];
  const activePrimitives = configuredPrimitives.map((prim) => {
    if (ctx.primitives[prim.name]) {
      return ctx.primitives[prim.name](group, prim.params);
    }
    return null;
  }).filter(Boolean);

  // --- CLEANUP ---
  group.userData.cleanup = () => {
    cancelAnimationFrame(frameId);
    timelines.forEach((t) => t.kill());
    activePrimitives.forEach((p) => p.cleanup?.());
    baseGeom.dispose();
    fieldMat.dispose();
    coreMat.dispose();
    bgGeo.dispose();
    bgMat.dispose();
    fieldInst.dispose();
    coreInst.dispose();
  };

  return group;
}
